-- =====================================================================
-- SDIP core schema — V1
-- Portable DDL: runs on PostgreSQL 16 (target) and H2 in PostgreSQL
-- compatibility mode (test / demo runtime). UUIDs are generated by the
-- application (Hibernate), not by the database.
-- =====================================================================

CREATE TABLE squad (
    id          UUID PRIMARY KEY,
    name        VARCHAR(120) NOT NULL,
    tenant_code VARCHAR(60)  NOT NULL,
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_squad_tenant_name UNIQUE (tenant_code, name)
);

CREATE TABLE app_user (
    id            UUID PRIMARY KEY,
    email         VARCHAR(255) NOT NULL UNIQUE,
    password_hash VARCHAR(100) NOT NULL,
    display_name  VARCHAR(160) NOT NULL,
    role          VARCHAR(30)  NOT NULL,
    squad_id      UUID REFERENCES squad (id),
    enabled       BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_app_user_role CHECK (role IN ('ADMIN', 'HEAD_COACH', 'PRACTITIONER', 'ANALYST'))
);

CREATE TABLE athlete (
    id           UUID PRIMARY KEY,
    squad_id     UUID NOT NULL REFERENCES squad (id),
    full_name    VARCHAR(200) NOT NULL,
    dob          DATE,
    email        VARCHAR(255),
    gender       VARCHAR(20),
    provisional  BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Email is a deterministic identity signal WITHIN a squad row-scope.
    -- Global uniqueness would couple tenants and crash cross-squad ingestion
    -- of athletes who legitimately share an address (C3 isolation).
    CONSTRAINT uq_athlete_squad_email UNIQUE (squad_id, email)
);
CREATE INDEX idx_athlete_squad ON athlete (squad_id);

CREATE TABLE training_session (
    id           UUID PRIMARY KEY,
    squad_id     UUID NOT NULL REFERENCES squad (id),
    external_ref VARCHAR(120),
    session_date DATE NOT NULL,
    session_type VARCHAR(60),
    name         VARCHAR(200),
    created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_training_session_squad_date ON training_session (squad_id, session_date);

-- Canonical metric dictionary (schema normalization backbone, §4.4)
CREATE TABLE metric_definition (
    code         VARCHAR(80) PRIMARY KEY,
    display_name VARCHAR(160) NOT NULL,
    unit         VARCHAR(30)  NOT NULL,
    category     VARCHAR(30)  NOT NULL,
    min_valid    DOUBLE PRECISION,
    max_valid    DOUBLE PRECISION,
    CONSTRAINT chk_metric_category CHECK (category IN ('GPS', 'FORCE', 'WELLNESS'))
);

CREATE TABLE metric_alias (
    alias       VARCHAR(200) PRIMARY KEY,
    metric_code VARCHAR(80) NOT NULL REFERENCES metric_definition (code)
);

-- User-configurable column mapping profiles (§4.2)
CREATE TABLE column_mapping_profile (
    id            UUID PRIMARY KEY,
    name          VARCHAR(120) NOT NULL UNIQUE,
    entity_type   VARCHAR(20)  NOT NULL,
    source_system VARCHAR(40)  NOT NULL,
    mappings      TEXT         NOT NULL,
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_profile_entity CHECK (entity_type IN ('GPS', 'FORCE', 'WELLNESS'))
);

-- Ingestion lineage (§4.4): one row per sync job or file upload
CREATE TABLE ingestion_batch (
    id             UUID PRIMARY KEY,
    batch_type     VARCHAR(20) NOT NULL,
    source_system  VARCHAR(40) NOT NULL,
    file_name      VARCHAR(300),
    status         VARCHAR(20) NOT NULL DEFAULT 'STARTED',
    rows_read      BIGINT NOT NULL DEFAULT 0,
    rows_written   BIGINT NOT NULL DEFAULT 0,
    rows_skipped   BIGINT NOT NULL DEFAULT 0,
    triggered_by   VARCHAR(255),
    started_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    finished_at    TIMESTAMP,
    duration_ms    BIGINT,
    error_summary  TEXT,
    CONSTRAINT chk_batch_type CHECK (batch_type IN ('FILE_CSV', 'FILE_XLSX', 'CONNECTOR')),
    CONSTRAINT chk_batch_status CHECK (status IN ('STARTED', 'COMPLETED', 'COMPLETED_WITH_SKIPS', 'FAILED'))
);
CREATE INDEX idx_ingestion_batch_started ON ingestion_batch (started_at);

CREATE TABLE ingestion_row_error (
    id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    batch_id    UUID NOT NULL REFERENCES ingestion_batch (id),
    row_number  INTEGER NOT NULL,
    raw_content TEXT,
    violation   TEXT NOT NULL,
    created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_row_error_batch ON ingestion_row_error (batch_id);

-- Reversible athlete identity links (§4.3). Never destructive: a revoked
-- link keeps its row (audit) and frees the natural key for re-linking.
CREATE TABLE athlete_source_link (
    id                UUID PRIMARY KEY,
    athlete_id        UUID NOT NULL REFERENCES athlete (id),
    source_system     VARCHAR(40)  NOT NULL,
    source_athlete_id VARCHAR(120) NOT NULL,
    match_tier        VARCHAR(20)  NOT NULL,
    match_score       DOUBLE PRECISION,
    status            VARCHAR(12)  NOT NULL DEFAULT 'ACTIVE',
    linked_by         VARCHAR(255),
    linked_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    unlinked_at       TIMESTAMP,
    CONSTRAINT uq_active_link UNIQUE (source_system, source_athlete_id),
    CONSTRAINT chk_link_tier CHECK (match_tier IN ('DETERMINISTIC', 'HEURISTIC', 'HUMAN_CONFIRMED')),
    CONSTRAINT chk_link_status CHECK (status IN ('ACTIVE', 'REVOKED'))
);
CREATE INDEX idx_link_athlete ON athlete_source_link (athlete_id);

CREATE TABLE link_quarantine (
    id                   UUID PRIMARY KEY,
    source_system        VARCHAR(40)  NOT NULL,
    source_athlete_id    VARCHAR(120) NOT NULL,
    candidate_athlete_id UUID REFERENCES athlete (id),
    score                DOUBLE PRECISION NOT NULL,
    payload              TEXT NOT NULL,
    status               VARCHAR(14) NOT NULL DEFAULT 'PENDING',
    created_at           TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved_by          VARCHAR(255),
    resolved_at          TIMESTAMP,
    resolution_note      TEXT,
    CONSTRAINT chk_quarantine_status CHECK (status IN ('PENDING', 'CONFIRMED', 'REJECTED'))
);
CREATE INDEX idx_quarantine_status ON link_quarantine (status);

-- Typed fact tables with full lineage (§4.4)
CREATE TABLE gps_metric (
    id                UUID PRIMARY KEY,
    athlete_id        UUID NOT NULL REFERENCES athlete (id),
    squad_id          UUID NOT NULL REFERENCES squad (id),
    session_id        UUID REFERENCES training_session (id),
    recorded_at       TIMESTAMP NOT NULL,
    total_distance_m  DOUBLE PRECISION,
    hsr_distance_m    DOUBLE PRECISION,
    player_load       DOUBLE PRECISION,
    max_velocity_kmh  DOUBLE PRECISION,
    session_minutes   DOUBLE PRECISION,
    source_system     VARCHAR(40)  NOT NULL,
    source_record_id  VARCHAR(300) NOT NULL,
    ingestion_batch_id UUID REFERENCES ingestion_batch (id),
    ingested_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_vendor_sync  TIMESTAMP,
    CONSTRAINT uq_gps_natural UNIQUE (source_system, source_record_id)
);
CREATE INDEX idx_gps_athlete_time ON gps_metric (athlete_id, recorded_at);
CREATE INDEX idx_gps_squad_time ON gps_metric (squad_id, recorded_at);

CREATE TABLE force_test (
    id                UUID PRIMARY KEY,
    athlete_id        UUID NOT NULL REFERENCES athlete (id),
    squad_id          UUID NOT NULL REFERENCES squad (id),
    test_type         VARCHAR(60) NOT NULL,
    tested_at         TIMESTAMP NOT NULL,
    peak_force_n      DOUBLE PRECISION,
    asymmetry_pct     DOUBLE PRECISION,
    rsi_modified      DOUBLE PRECISION,
    peak_power_w      DOUBLE PRECISION,
    source_system     VARCHAR(40)  NOT NULL,
    source_record_id  VARCHAR(300) NOT NULL,
    ingestion_batch_id UUID REFERENCES ingestion_batch (id),
    ingested_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_vendor_sync  TIMESTAMP,
    CONSTRAINT uq_force_natural UNIQUE (source_system, source_record_id)
);
CREATE INDEX idx_force_athlete_time ON force_test (athlete_id, tested_at);

CREATE TABLE wellness_survey (
    id                UUID PRIMARY KEY,
    athlete_id        UUID NOT NULL REFERENCES athlete (id),
    squad_id          UUID NOT NULL REFERENCES squad (id),
    survey_date       DATE NOT NULL,
    sleep_score       DOUBLE PRECISION,
    fatigue           DOUBLE PRECISION,
    soreness          DOUBLE PRECISION,
    stress            DOUBLE PRECISION,
    mood              DOUBLE PRECISION,
    source_system     VARCHAR(40)  NOT NULL,
    source_record_id  VARCHAR(300) NOT NULL,
    ingestion_batch_id UUID REFERENCES ingestion_batch (id),
    ingested_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_vendor_sync  TIMESTAMP,
    CONSTRAINT uq_wellness_natural UNIQUE (source_system, source_record_id)
);
CREATE INDEX idx_wellness_athlete_date ON wellness_survey (athlete_id, survey_date);

-- Append-only audit trail (§4.5). Immutability for the PG deployment is
-- additionally enforced by database rules in a PG-only migration.
CREATE TABLE audit_event (
    id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    actor_email VARCHAR(255) NOT NULL,
    actor_role  VARCHAR(30)  NOT NULL,
    action      VARCHAR(60)  NOT NULL,
    entity_type VARCHAR(60),
    entity_id   VARCHAR(80),
    details     TEXT,
    created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_audit_created ON audit_event (created_at);
CREATE INDEX idx_audit_actor ON audit_event (actor_email);

-- Connector watermarks (§4.1) and encrypted vendor credentials (§4.5)
CREATE TABLE connector_state (
    vendor         VARCHAR(40) PRIMARY KEY,
    last_synced_at TIMESTAMP,
    updated_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE vendor_credential (
    vendor       VARCHAR(40) PRIMARY KEY,
    payload_enc  BYTEA NOT NULL,
    updated_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by   VARCHAR(255)
);
